#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    unsigned char key[32] = {0};
    unsigned char nonce[12] = {0};
    unsigned char aad[32] = {0};
    size_t n = 40000000UL;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n + 16);
    memset(pt, 1, n);
    int outlen = 0, tmplen = 0;

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    /* warmup */
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct + outlen, &tmplen);
    unsigned char tag[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);

    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("C EVP %d x 40MB: %.3f s, avg %.1f ms, throughput %.0f MB/s\n",
           reps, t1-t0, (t1-t0)/reps*1000, (40.0*reps)/(t1-t0));
    printf("tag0=%02x ct0=%02x\n", tag[0], ct[0]);
    return 0;
}
EOF
