#define MAX_T 8
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

typedef struct {
    pthread_t th;
    int id;
    EVP_CIPHER_CTX *ctx;
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned char iv[16];
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int ready; /* main -> worker: work available */
    int done;  /* worker -> main */
    int stop;
} worker_t;

static void *worker_fn(void *arg){
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for(;;){
        while(!w->ready && !w->stop) pthread_cond_wait(&w->cv, &w->mu);
        if(w->stop){ pthread_mutex_unlock(&w->mu); return NULL; }
        w->ready = 0;
        pthread_mutex_unlock(&w->mu);

