            pthread_mutex_init(&ws[i].mu, NULL);
            pthread_cond_init(&ws[i].cv, NULL);
            size_t off=i*chunk;
            size_t len=(i==nt-1)?n-off:chunk;
            ws[i].in=in+off; ws[i].out=out+off; ws[i].len=len;
            uint32_t ctr=1+(uint32_t)(off/64);
            ws[i].iv[0]=ctr; ws[i].iv[1]=ctr>>8; ws[i].iv[2]=ctr>>16; ws[i].iv[3]=ctr>>24;
            memcpy(ws[i].iv+4, nonce, 12);
            pthread_create(&ws[i].th, NULL, worker_fn, &ws[i]);
        }
        /* warmup */
        for(int i=0;i<nt;i++){ pthread_mutex_lock(&ws[i].mu); ws[i].done=0; ws[i].ready=1; pthread_cond_signal(&ws[i].cv); pthread_mutex_unlock(&ws[i].mu); }
        for(int i=0;i<nt;i++){ pthread_mutex_lock(&ws[i].mu); while(!ws[i].done) pthread_cond_wait(&ws[i].cv,&ws[i].mu); pthread_mutex_unlock(&ws[i].mu); }

        double t0=now();
        int reps=10;
        for(int r=0;r<reps;r++){
            for(int i=0;i<nt;i++){ pthread_mutex_lock(&ws[i].mu); ws[i].done=0; ws[i].ready=1; pthread_cond_signal(&ws[i].cv); pthread_mutex_unlock(&ws[i].mu); }
            for(int i=0;i<nt;i++){ pthread_mutex_lock(&ws[i].mu); while(!ws[i].done) pthread_cond_wait(&ws[i].cv,&ws[i].mu); pthread_mutex_unlock(&ws[i].mu); }
        }
