#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

/* copy kernel that cannot be DCE'd */
static void copy_nt(uint8_t *dst, const uint8_t *src, size_t n){
    size_t i=0;
    for(; i+32<=n; i+=32){
        __asm__ volatile(
            "vmovdqu (%1), %%ymm0\n\t"
            "vmovdqu %%ymm0, (%0)\n\t"
            :
            : "r"(dst+i), "r"(src+i)
            : "ymm0", "memory");
    }
    for(;i<n;i++) dst[i]=src[i];
}
static void triad(uint8_t *dst, const uint8_t *a, const uint8_t *b, size_t n){
    /* dst = a + b, 32 bytes at a time, forces 2 reads + 1 write */
    size_t i=0;
    for(; i+32<=n; i+=32){
        __asm__ volatile(
            "vmovdqu (%1), %%ymm0\n\t"
            "vmovdqu (%2), %%ymm1\n\t"
            "vpaddb %%ymm1, %%ymm0, %%ymm0\n\t"
            "vmovdqu %%ymm0, (%0)\n\t"
            :
            : "r"(dst+i), "r"(a+i), "r"(b+i)
            : "ymm0", "ymm1", "memory");
    }
}
typedef struct { uint8_t *d,*a,*b; size_t n; int kind; } job;
static void *worker(void *arg){
    job *j=arg;
    if(j->kind==0) copy_nt(j->d, j->a, j->n);
    else triad(j->d, j->a, j->b, j->n);
    return NULL;
}
int main(){
    size_t n=40000000;
    uint8_t *a=aligned_alloc(64,n), *b=aligned_alloc(64,n), *c=aligned_alloc(64,n);
    memset(a,1,n); memset(b,2,n); memset(c,3,n);
    for(int nt=1; nt<=6; nt+= (nt==1?1: (nt==2?2:2))){
        if(nt==5) continue;
        size_t chunk=n/nt;
        pthread_t th[8]; job jobs[8];
        /* warmup */
        for(int i=0;i<nt;i++){
            size_t off=i*chunk, len=(i==nt-1)?n-off:chunk;
            jobs[i]=(job){c+off,a+off,b+off,len,0};
            pthread_create(&th[i],NULL,worker,&jobs[i]);
        }
        for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
        int reps=8;
        double t0=now();
        for(int r=0;r<reps;r++){
            for(int i=0;i<nt;i++){
                size_t off=i*chunk, len=(i==nt-1)?n-off:chunk;
                jobs[i]=(job){c+off,a+off,b+off,len,0};
                pthread_create(&th[i],NULL,worker,&jobs[i]);
            }
            for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
        }
        double t1=now();
        volatile uint8_t sink=c[0]+c[n/2]+c[n-1];
        printf("COPY %d thr (incl create): avg %.2f ms, one-way %.1f GB/s sink %u\n",
            nt,(t1-t0)/reps*1000, (40.0*reps)/(t1-t0)/1000.0, sink);
    }
    /* serial no threads */
