#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

#define NT 4
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

typedef struct {
    pthread_t th;
    EVP_CIPHER_CTX *cctx;
    void *pctx;
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned char iv[16];
    int is_first;
    const unsigned char *aad;
    size_t aad_len;
    unsigned char lens[16];
    int do_lens;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int ready, done, stop;
} W;

static void *fn(void *arg){
    W *w=arg;
    pthread_mutex_lock(&w->mu);
    for(;;){
        while(!w->ready && !w->stop) pthread_cond_wait(&w->cv, &w->mu);
        if(w->stop){ pthread_mutex_unlock(&w->mu); return NULL; }
        w->ready=0;
        pthread_mutex_unlock(&w->mu);

        int ol=0;
        EVP_EncryptInit_ex(w->cctx, NULL, NULL, NULL, w->iv);
        EVP_EncryptUpdate(w->cctx, w->out, &ol, w->in, (int)w->len);
        /* poly over ciphertext (and aad/lens if this chunk owns them) */
        if(w->is_first && w->aad_len){
            Poly1305_Update(w->pctx, w->aad, w->aad_len);
            size_t pad = (16 - (w->aad_len & 15)) & 15;
            if(pad){
                unsigned char z[16]={0};
                Poly1305_Update(w->pctx, z, pad);
            }
        }
        Poly1305_Update(w->pctx, w->out, w->len);
        if(w->do_lens){
            size_t pad = (16 - (w->len & 15)) & 15;
            /* NOTE: padding is for TOTAL ciphertext length, not chunk. Only last chunk handles tail pad + lengths.
               Caller sets do_lens only on last and has already accounted. We just append lens here;
               tail pad is included by caller in a separate buffer if needed. For this bench, lengths are multiples of 64 so no ct pad. */
            Poly1305_Update(w->pctx, w->lens, 16);
        }

        pthread_mutex_lock(&w->mu);
        w->done=1;
        pthread_cond_signal(&w->cv);
    }
}

int main(){
    size_t n=40000000;
    unsigned char *in=aligned_alloc(64,n);
    unsigned char *out=aligned_alloc(64,n);
    memset(in, 0x5a, n);
    unsigned char key[32];
    for(int i=0;i<32;i++) key[i]=i+1;
    unsigned char nonce[12];
    for(int i=0;i<12;i++) nonce[i]=i+3;
    unsigned char aad[32];
    memset(aad, 0x11, 32);

    size_t csz=Poly1305_ctx_size();
    W ws[NT];
    size_t chunk=(n/NT)&~(size_t)63;
    /* poly key from chacha block 0 */
    unsigned char polykey_block[64]={0};
    unsigned char zeros[64]={0};
    EVP_CIPHER_CTX *kctx=EVP_CIPHER_CTX_new();
    unsigned char iv0[16]={0};
    memcpy(iv0+4, nonce, 12);
    EVP_EncryptInit_ex(kctx, EVP_chacha20(), NULL, key, iv0);
    int ol=0;
    EVP_EncryptUpdate(kctx, polykey_block, &ol, zeros, 64);

    for(int i=0;i<NT;i++){
        memset(&ws[i],0,sizeof(ws[i]));
        ws[i].cctx=EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ws[i].cctx, EVP_chacha20(), NULL, key, NULL);
        ws[i].pctx=malloc(csz);
        Poly1305_Init(ws[i].pctx, polykey_block); /* will re-init each run */
        pthread_mutex_init(&ws[i].mu,NULL);
        pthread_cond_init(&ws[i].cv,NULL);
        size_t off=i*chunk;
        size_t len=(i==NT-1)?n-off:chunk;
        ws[i].in=in+off; ws[i].out=out+off; ws[i].len=len;
        uint32_t ctr=1+(uint32_t)(off/64);
        ws[i].iv[0]=ctr; ws[i].iv[1]=ctr>>8; ws[i].iv[2]=ctr>>16; ws[i].iv[3]=ctr>>24;
        memcpy(ws[i].iv+4, nonce, 12);
        ws[i].is_first=(i==0);
        ws[i].aad=aad; ws[i].aad_len=32;
        ws[i].do_lens=(i==NT-1);
        uint64_t al=32, cl=n;
        memcpy(ws[i].lens, &al, 8);
        memcpy(ws[i].lens+8, &cl, 8);
        pthread_create(&ws[i].th, NULL, fn, &ws[i]);
    }

    int reps=8;
    /* warmup */
    for(int i=0;i<NT;i++){ Poly1305_Init(ws[i].pctx, polykey_block); }
    for(int i=0;i<NT;i++){ pthread_mutex_lock(&ws[i].mu); ws[i].done=0; ws[i].ready=1; pthread_cond_signal(&ws[i].cv); pthread_mutex_unlock(&ws[i].mu); }
    for(int i=0;i<NT;i++){ pthread_mutex_lock(&ws[i].mu); while(!ws[i].done) pthread_cond_wait(&ws[i].cv,&ws[i].mu); pthread_mutex_unlock(&ws[i].mu); }

    double t0=now();
    for(int r=0;r<reps;r++){
        for(int i=0;i<NT;i++) Poly1305_Init(ws[i].pctx, polykey_block);
        for(int i=0;i<NT;i++){ pthread_mutex_lock(&ws[i].mu); ws[i].done=0; ws[i].ready=1; pthread_cond_signal(&ws[i].cv); pthread_mutex_unlock(&ws[i].mu); }
        for(int i=0;i<NT;i++){ pthread_mutex_lock(&ws[i].mu); while(!ws[i].done) pthread_cond_wait(&ws[i].cv,&ws[i].mu); pthread_mutex_unlock(&ws[i].mu); }
    }
    double t1=now();
    printf("parallel aead-ish %d thr: avg %.2f ms, %.0f MB/s\n", NT, (t1-t0)/reps*1000, 40.0*reps/(t1-t0));

    /* serial reference via EVP aead */
    EVP_CIPHER_CTX *actx=EVP_CIPHER_CTX_new();
    unsigned char *ct2=malloc(n+16);
    unsigned char tag[16];
    EVP_EncryptInit_ex(actx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(actx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(actx, NULL, NULL, key, nonce);
    t0=now();
    int sreps=5;
    for(int r=0;r<sreps;r++){
        EVP_EncryptInit_ex(actx, NULL, NULL, NULL, nonce);
        EVP_EncryptUpdate(actx, NULL, &ol, aad, 32);
        EVP_EncryptUpdate(actx, ct2, &ol, in, (int)n);
        int tmplen=0;
        EVP_EncryptFinal_ex(actx, ct2+ol, &tmplen);
        EVP_CIPHER_CTX_ctrl(actx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1=now();
    printf("serial EVP aead: avg %.2f ms, %.0f MB/s\n", (t1-t0)/sreps*1000, 40.0*sreps/(t1-t0));
    printf("ciphertext match parallel vs serial: %d\n", memcmp(out, ct2, n)==0);

    /* combine poly states? For now just print that we have partial macs.
       We'll verify combined tag in a later step. */
    return 0;
}
