#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

static void copy_avx(uint8_t *d, const uint8_t *s, size_t n){
    size_t i=0;
    for(; i+128<=n; i+=128){
        __m256i a=_mm256_loadu_si256((const __m256i*)(s+i));
        __m256i b=_mm256_loadu_si256((const __m256i*)(s+i+32));
        __m256i c=_mm256_loadu_si256((const __m256i*)(s+i+64));
        __m256i e=_mm256_loadu_si256((const __m256i*)(s+i+96));
        _mm256_storeu_si256((__m256i*)(d+i), a);
        _mm256_storeu_si256((__m256i*)(d+i+32), b);
        _mm256_storeu_si256((__m256i*)(d+i+64), c);
        _mm256_storeu_si256((__m256i*)(d+i+96), e);
    }
    for(;i<n;i++) d[i]=s[i];
}
static void copy_nt(uint8_t *d, const uint8_t *s, size_t n){
    size_t i=0;
    for(; i+128<=n; i+=128){
        __m256i a=_mm256_loadu_si256((const __m256i*)(s+i));
        __m256i b=_mm256_loadu_si256((const __m256i*)(s+i+32));
        __m256i c=_mm256_loadu_si256((const __m256i*)(s+i+64));
        __m256i e=_mm256_loadu_si256((const __m256i*)(s+i+96));
        _mm256_stream_si256((__m256i*)(d+i), a);
        _mm256_stream_si256((__m256i*)(d+i+32), b);
        _mm256_stream_si256((__m256i*)(d+i+64), c);
        _mm256_stream_si256((__m256i*)(d+i+96), e);
    }
    _mm_sfence();
    for(;i<n;i++) d[i]=s[i];
}
typedef struct { uint8_t *d,*s; size_t n; int kind; } job;
static void *worker(void *a){
    job *j=a;
    if(j->kind==0) copy_avx(j->d,j->s,j->n);
    else copy_nt(j->d,j->s,j->n);
    return NULL;
}
int main(){
    size_t n=256UL<<20; /* 256 MB */
    uint8_t *a=aligned_alloc(64,n), *b=aligned_alloc(64,n);
    memset(a,1,n);
    for(int kind=0; kind<2; kind++){
        for(int nt=1; nt<=6; nt*=2){
            size_t chunk=n/nt;
            pthread_t th[8]; job jobs[8];
            int reps=4;
            double t0=now();
            for(int r=0;r<reps;r++){
                for(int i=0;i<nt;i++){
                    size_t off=i*chunk, len=(i==nt-1)?n-off:chunk;
                    jobs[i]=(job){b+off,a+off,len,kind};
                    pthread_create(&th[i],NULL,worker,&jobs[i]);
                }
                for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
            }
            double t1=now();
            volatile uint8_t sink=b[0]+b[n-1];
            double mb = (n/1e6)*reps;
            printf("%s %d thr 256MB: avg %.1f ms, one-way %.1f GB/s, traffic %.1f GB/s sink %u\n",
                kind?"NT":"ST", nt, (t1-t0)/reps*1000, mb/(t1-t0)/1000.0, 2*mb/(t1-t0)/1000.0, sink);
        }
    }
    return 0;
}
