/* Parallel ChaCha20-Poly1305 (RFC 8439) using OpenSSL ChaCha20 + our Poly1305.
   Chunks are processed independently; Poly1305 accumulators are combined. */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

#define NT 4

/* ---------- Poly1305 (26-bit limbs, donna-style), serial but tiny relative to chacha ---------- */

typedef struct {
    uint32_t r[5];
    uint32_t h[5];
    uint32_t pad[4];
    uint8_t buf[16];
    size_t buf_used;
    /* precomputed r*5 */
    uint32_t s1, s2, s3, s4;
} poly_st;

static inline uint32_t load32(const uint8_t *p) {
    uint32_t v;
    memcpy(&v, p, 4);
    return v;
}
static inline void store32(uint8_t *p, uint32_t v) { memcpy(p, &v, 4); }

static void poly_init(poly_st *st, const uint8_t key[32]) {
    memset(st, 0, sizeof(*st));
    uint32_t t0 = load32(key);
    uint32_t t1 = load32(key + 4);
    uint32_t t2 = load32(key + 8);
    uint32_t t3 = load32(key + 12);
    st->r[0] = t0 & 0x3ffffff;
    st->r[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffff03;
    st->r[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffc0ff;
    st->r[3] = ((t2 >> 14) | (t3 << 18)) & 0x3f03fff;
    st->r[4] = (t3 >> 8) & 0x00fffff;
    st->s1 = st->r[1] * 5;
    st->s2 = st->r[2] * 5;
    st->s3 = st->r[3] * 5;
    st->s4 = st->r[4] * 5;
    st->pad[0] = load32(key + 16);
    st->pad[1] = load32(key + 20);
    st->pad[2] = load32(key + 24);
    st->pad[3] = load32(key + 28);
}

static void poly_blocks(poly_st *st, const uint8_t *m, size_t bytes, uint32_t hibit) {
    const uint32_t r0 = st->r[0], r1 = st->r[1], r2 = st->r[2], r3 = st->r[3], r4 = st->r[4];
    const uint32_t s1 = st->s1, s2 = st->s2, s3 = st->s3, s4 = st->s4;
    uint32_t h0 = st->h[0], h1 = st->h[1], h2 = st->h[2], h3 = st->h[3], h4 = st->h[4];
    while (bytes >= 16) {
        uint32_t t0 = load32(m);
        uint32_t t1 = load32(m + 4);
        uint32_t t2 = load32(m + 8);
        uint32_t t3 = load32(m + 12);
        h0 += t0 & 0x3ffffff;
        h1 += ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
        h2 += ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
        h3 += ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
        h4 += (t3 >> 8) | hibit;

        uint64_t d0 = (uint64_t)h0 * r0 + (uint64_t)h1 * s4 + (uint64_t)h2 * s3 + (uint64_t)h3 * s2 + (uint64_t)h4 * s1;
        uint64_t d1 = (uint64_t)h0 * r1 + (uint64_t)h1 * r0 + (uint64_t)h2 * s4 + (uint64_t)h3 * s3 + (uint64_t)h4 * s2;
        uint64_t d2 = (uint64_t)h0 * r2 + (uint64_t)h1 * r1 + (uint64_t)h2 * r0 + (uint64_t)h3 * s4 + (uint64_t)h4 * s3;
        uint64_t d3 = (uint64_t)h0 * r3 + (uint64_t)h1 * r2 + (uint64_t)h2 * r1 + (uint64_t)h3 * r0 + (uint64_t)h4 * s4;
        uint64_t d4 = (uint64_t)h0 * r4 + (uint64_t)h1 * r3 + (uint64_t)h2 * r2 + (uint64_t)h3 * r1 + (uint64_t)h4 * r0;

        uint64_t c;
        c = d0 >> 26; h0 = (uint32_t)d0 & 0x3ffffff; d1 += c;
        c = d1 >> 26; h1 = (uint32_t)d1 & 0x3ffffff; d2 += c;
        c = d2 >> 26; h2 = (uint32_t)d2 & 0x3ffffff; d3 += c;
        c = d3 >> 26; h3 = (uint32_t)d3 & 0x3ffffff; d4 += c;
        c = d4 >> 26; h4 = (uint32_t)d4 & 0x3ffffff; h0 += (uint32_t)c * 5;
        c = h0 >> 26; h0 &= 0x3ffffff; h1 += (uint32_t)c;

        m += 16;
        bytes -= 16;
    }
    st->h[0] = h0; st->h[1] = h1; st->h[2] = h2; st->h[3] = h3; st->h[4] = h4;
}

static void poly_update(poly_st *st, const uint8_t *m, size_t bytes) {
    if (st->buf_used) {
        size_t want = 16 - st->buf_used;
        if (want > bytes) want = bytes;
        memcpy(st->buf + st->buf_used, m, want);
        st->buf_used += want;
        m += want;
        bytes -= want;
        if (st->buf_used == 16) {
            poly_blocks(st, st->buf, 16, 1u << 24);
            st->buf_used = 0;
        }
    }
    if (bytes >= 16) {
        size_t n = bytes & ~(size_t)15;
        poly_blocks(st, m, n, 1u << 24);
        m += n;
        bytes -= n;
    }
    if (bytes) {
        memcpy(st->buf + st->buf_used, m, bytes);
        st->buf_used += bytes;
    }
}

static void poly_finish(poly_st *st, uint8_t mac[16]) {
    if (st->buf_used) {
        st->buf[st->buf_used] = 1;
        for (size_t i = st->buf_used + 1; i < 16; i++) st->buf[i] = 0;
        poly_blocks(st, st->buf, 16, 0);
        st->buf_used = 0;
    }
    uint32_t h0 = st->h[0], h1 = st->h[1], h2 = st->h[2], h3 = st->h[3], h4 = st->h[4];
    uint32_t c = h1 >> 26; h1 &= 0x3ffffff; h2 += c;
    c = h2 >> 26; h2 &= 0x3ffffff; h3 += c;
    c = h3 >> 26; h3 &= 0x3ffffff; h4 += c;
    c = h4 >> 26; h4 &= 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    uint32_t g0 = h0 + 5; c = g0 >> 26; g0 &= 0x3ffffff;
    uint32_t g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    uint32_t g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    uint32_t g4 = h4 + c - (1u << 26);

    uint32_t mask = (g4 >> 31) - 1u;
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    uint64_t f0 = (h0 | ((uint64_t)h1 << 26)) + st->pad[0];
    uint64_t f1 = ((h1 >> 6) | ((uint64_t)h2 << 20)) + st->pad[1];
    uint64_t f2 = ((h2 >> 12) | ((uint64_t)h3 << 14)) + st->pad[2];
    uint64_t f3 = ((h3 >> 18) | ((uint64_t)h4 << 8)) + st->pad[3];
    f1 += f0 >> 32;
    f2 += f1 >> 32;
    f3 += f2 >> 32;
    store32(mac + 0, (uint32_t)f0);
    store32(mac + 4, (uint32_t)f1);
    store32(mac + 8, (uint32_t)f2);
    store32(mac + 12, (uint32_t)f3);
}

/* Multiply accumulator by r^(nblocks) and add other accumulator.
   h and r are 26-bit limbs. nblocks is the number of 16-byte blocks already
   absorbed into the "later" accumulator, so we scale the earlier one by r^nblocks.
   We compute r^nblocks by exponentiation, then one mul. */
static void poly_mul(uint32_t h[5], const uint32_t r[5]) {
    uint32_t r0=r[0], r1=r[1], r2=r[2], r3=r[3], r4=r[4];
    uint32_t s1=r1*5, s2=r2*5, s3=r3*5, s4=r4*5;
    uint32_t h0=h[0], h1=h[1], h2=h[2], h3=h[3], h4=h[4];
    uint64_t d0 = (uint64_t)h0*r0 + (uint64_t)h1*s4 + (uint64_t)h2*s3 + (uint64_t)h3*s2 + (uint64_t)h4*s1;
    uint64_t d1 = (uint64_t)h0*r1 + (uint64_t)h1*r0 + (uint64_t)h2*s4 + (uint64_t)h3*s3 + (uint64_t)h4*s2;
    uint64_t d2 = (uint64_t)h0*r2 + (uint64_t)h1*r1 + (uint64_t)h2*r0 + (uint64_t)h3*s4 + (uint64_t)h4*s3;
    uint64_t d3 = (uint64_t)h0*r3 + (uint64_t)h1*r2 + (uint64_t)h2*r1 + (uint64_t)h3*r0 + (uint64_t)h4*s4;
    uint64_t d4 = (uint64_t)h0*r4 + (uint64_t)h1*r3 + (uint64_t)h2*r2 + (uint64_t)h3*r1 + (uint64_t)h4*r0;
    uint64_t c;
    c=d0>>26; h0=(uint32_t)d0 & 0x3ffffff; d1+=c;
    c=d1>>26; h1=(uint32_t)d1 & 0x3ffffff; d2+=c;
    c=d2>>26; h2=(uint32_t)d2 & 0x3ffffff; d3+=c;
    c=d3>>26; h3=(uint32_t)d3 & 0x3ffffff; d4+=c;
    c=d4>>26; h4=(uint32_t)d4 & 0x3ffffff; h0+=(uint32_t)c*5;
    c=h0>>26; h0&=0x3ffffff; h1+=(uint32_t)c;
    h[0]=h0; h[1]=h1; h[2]=h2; h[3]=h3; h[4]=h4;
}

static void poly_pow(uint32_t out[5], const uint32_t r[5], uint64_t n) {
    /* out = r^n  (as a field element, 26-bit limbs). n >= 1 */
    uint32_t base[5] = {r[0], r[1], r[2], r[3], r[4]};
    uint32_t acc[5] = {1, 0, 0, 0, 0};
    while (n) {
        if (n & 1) poly_mul(acc, base);
        n >>= 1;
        if (n) {
            uint32_t sq[5] = {base[0], base[1], base[2], base[3], base[4]};
            poly_mul(base, sq);
        }
    }
    memcpy(out, acc, sizeof(acc));
}

static void poly_add(uint32_t h[5], const uint32_t o[5]) {
    uint64_t c;
    uint64_t a0 = (uint64_t)h[0] + o[0];
    uint64_t a1 = (uint64_t)h[1] + o[1];
    uint64_t a2 = (uint64_t)h[2] + o[2];
    uint64_t a3 = (uint64_t)h[3] + o[3];
    uint64_t a4 = (uint64_t)h[4] + o[4];
    c=a0>>26; h[0]=(uint32_t)a0 & 0x3ffffff; a1+=c;
    c=a1>>26; h[1]=(uint32_t)a1 & 0x3ffffff; a2+=c;
    c=a2>>26; h[2]=(uint32_t)a2 & 0x3ffffff; a3+=c;
    c=a3>>26; h[3]=(uint32_t)a3 & 0x3ffffff; a4+=c;
    c=a4>>26; h[4]=(uint32_t)a4 & 0x3ffffff; h[0]+=(uint32_t)c*5;
    c=h[0]>>26; h[0]&=0x3ffffff; h[1]+=(uint32_t)c;
}

/* ---------- persistent thread pool ---------- */

typedef struct {
    pthread_t th;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int ready, done, stop;
    EVP_CIPHER_CTX *ctx;
    const uint8_t *in;
    uint8_t *out;
    size_t len;
    uint8_t iv[16];
    poly_st poly;
    const uint8_t *poly_key; /* 32 bytes, set by main before signal; worker inits */
    int init_poly;
} worker_t;

static worker_t g_workers[NT];
static int g_inited = 0;
static pthread_mutex_t g_init_mu = PTHREAD_MUTEX_INITIALIZER;

static void *worker_fn(void *arg) {
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (!w->ready && !w->stop) pthread_cond_wait(&w->cv, &w->mu);
        if (w->stop) { pthread_mutex_unlock(&w->mu); return NULL; }
        w->ready = 0;
        pthread_mutex_unlock(&w->mu);

        if (w->init_poly) poly_init(&w->poly, w->poly_key);

        int ol = 0;
        EVP_EncryptInit_ex(w->ctx, NULL, NULL, NULL, w->iv);
        EVP_EncryptUpdate(w->ctx, w->out, &ol, w->in, (int)w->len);
        /* MAC the ciphertext chunk. Caller guarantees chunk length is a multiple of 16
           except possibly the last chunk, which may have a partial block — poly_update handles it. */
        poly_update(&w->poly, w->out, w->len);

        pthread_mutex_lock(&w->mu);
        w->done = 1;
        pthread_cond_signal(&w->cv);
    }
}

static void ensure_pool(const uint8_t key[32]) {
    pthread_mutex_lock(&g_init_mu);
    if (!g_inited) {
        for (int i = 0; i < NT; i++) {
            worker_t *w = &g_workers[i];
            memset(w, 0, sizeof(*w));
            pthread_mutex_init(&w->mu, NULL);
            pthread_cond_init(&w->cv, NULL);
            w->ctx = EVP_CIPHER_CTX_new();
            EVP_EncryptInit_ex(w->ctx, EVP_chacha20(), NULL, key, NULL);
            pthread_create(&w->th, NULL, worker_fn, w);
        }
        g_inited = 1;
    } else {
        /* re-key if needed: always reinit cipher key (cheap) */
        for (int i = 0; i < NT; i++) {
            EVP_EncryptInit_ex(g_workers[i].ctx, NULL, NULL, key, NULL);
        }
    }
    pthread_mutex_unlock(&g_init_mu);
}

/* ---------- AEAD ---------- */

static int aead_encrypt(uint8_t *ct, uint8_t tag[16],
                        const uint8_t *pt, size_t pt_len,
                        const uint8_t *aad, size_t aad_len,
                        const uint8_t key[32], const uint8_t nonce[12]) {
    ensure_pool(key);

    /* poly1305 one-time key = ChaCha20(key, counter=0, nonce) over 32 zero bytes */
    uint8_t poly_key_block[64];
    uint8_t zeros[64] = {0};
    uint8_t iv0[16] = {0, 0, 0, 0};
    memcpy(iv0 + 4, nonce, 12);
    EVP_CIPHER_CTX *kctx = g_workers[0].ctx; /* borrow? NO — worker may be idle but ctx is not thread-safe to share.
                                                 Use a dedicated context. */
    static EVP_CIPHER_CTX *keyctx = NULL;
    if (!keyctx) {
        keyctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(keyctx, EVP_chacha20(), NULL, key, iv0);
    } else {
        EVP_EncryptInit_ex(keyctx, NULL, NULL, key, iv0);
    }
    int ol = 0;
    if (EVP_EncryptUpdate(keyctx, poly_key_block, &ol, zeros, 64) != 1) return -1;

    /* Split plaintext into NT chunks, each a multiple of 64 bytes except the last. */
    size_t chunk = pt_len / NT;
    chunk &= ~(size_t)63;
    if (chunk == 0) {
        /* tiny message: do it on worker 0 only, others idle with len 0 */
        chunk = pt_len;
    }

    size_t off = 0;
    int nused = 0;
    for (int i = 0; i < NT; i++) {
        size_t len;
        if (i == NT - 1 || off >= pt_len) {
            len = (off < pt_len) ? (pt_len - off) : 0;
        } else {
            len = chunk;
            if (off + len > pt_len) len = pt_len - off;
        }
        worker_t *w = &g_workers[i];
        w->in = pt + off;
        w->out = ct + off;
        w->len = len;
        uint32_t ctr = 1u + (uint32_t)(off / 64);
        w->iv[0] = (uint8_t)ctr;
        w->iv[1] = (uint8_t)(ctr >> 8);
        w->iv[2] = (uint8_t)(ctr >> 16);
        w->iv[3] = (uint8_t)(ctr >> 24);
        memcpy(w->iv + 4, nonce, 12);
        w->poly_key = poly_key_block;
        w->init_poly = 1;
        off += len;
        nused = i + 1;
        if (off >= pt_len && i < NT - 1) {
            /* zero out remaining workers */
            for (int j = i + 1; j < NT; j++) {
                g_workers[j].len = 0;
                g_workers[j].in = pt;
                g_workers[j].out = ct;
                g_workers[j].init_poly = 1;
                g_workers[j].poly_key = poly_key_block;
                memset(g_workers[j].iv, 0, 16);
            }
            nused = NT;
            break;
        }
    }

    for (int i = 0; i < NT; i++) {
        pthread_mutex_lock(&g_workers[i].mu);
        g_workers[i].done = 0;
        g_workers[i].ready = 1;
        pthread_cond_signal(&g_workers[i].cv);
        pthread_mutex_unlock(&g_workers[i].mu);
    }
    for (int i = 0; i < NT; i++) {
        pthread_mutex_lock(&g_workers[i].mu);
        while (!g_workers[i].done) pthread_cond_wait(&g_workers[i].cv, &g_workers[i].mu);
        pthread_mutex_unlock(&g_workers[i].mu);
    }

    /* Combine poly accumulators.
       Each worker absorbed its chunk (possibly with an internal partial block only on the last worker,
       since earlier chunks are multiples of 64).
       AAD and length block are absorbed serially onto the combined state. */

    /* For workers whose chunk length is a multiple of 16, h is the accumulator after exactly
       len/16 blocks, and buf_used == 0. The last worker may have a partial block in buf.
       We combine full-block accumulators first, then feed the tail + aad + lengths through one state. */

    /* Build combined accumulator of all FULL blocks in order.
       Worker i absorbed b_i = len_i/16 full blocks (and maybe a tail).
       combined = (...((h0 * r^{b1} + h1) * r^{b2} + h2) ...)
       Tails: only the last non-empty worker can have a tail (earlier lens are multiples of 64). */
    uint32_t H[5] = {0, 0, 0, 0, 0};
    int have = 0;
    size_t full_blocks_after = 0; /* not used */
    (void)full_blocks_after; (void)nused;

    for (int i = 0; i < NT; i++) {
        worker_t *w = &g_workers[i];
        size_t full = w->len & ~(size_t)15;
        uint64_t blocks = full / 16;
        if (!have) {
            memcpy(H, w->poly.h, sizeof(H));
            have = 1;
        } else if (blocks || w->poly.h[0] | w->poly.h[1] | w->poly.h[2] | w->poly.h[3] | w->poly.h[4]) {
            if (blocks) {
                uint32_t rp[5];
                poly_pow(rp, w->poly.r, blocks);
                poly_mul(H, rp);
            }
            poly_add(H, w->poly.h);
        }
    }

    /* Now H is the accumulator as if all full blocks were processed, WITHOUT the hibit adjustment issues.
       Each worker's poly_blocks added hibit (1<<24) per block, which is exactly what serial would do.
       Combining via r^{blocks} is correct for full blocks. Good. */

    poly_st final;
    poly_init(&final, poly_key_block);
    memcpy(final.h, H, sizeof(H));

    /* tail of last non-empty chunk */
    for (int i = NT - 1; i >= 0; i--) {
        if (g_workers[i].len) {
            size_t tail = g_workers[i].poly.buf_used;
            if (tail) poly_update(&final, g_workers[i].poly.buf, tail);
            break;
        }
    }

    /* AAD is supposed to come BEFORE ciphertext. We absorbed ciphertext first. That is wrong
       unless aad is empty.
       Fix: we must absorb AAD first. Easiest correct approach: absorb AAD into a fresh state,
       then multiply by r^{ct_blocks_including_tail_padding} and add ciphertext accumulator.
       Let's redo combination properly below if aad_len != 0. For the common case aad is 0 or 32.
    */
    /* RESTART combination correctly. */
    {
        poly_st aad_st;
        poly_init(&aad_st, poly_key_block);
        if (aad && aad_len) {
            poly_update(&aad_st, aad, aad_len);
            size_t pad = (16 - (aad_len & 15)) & 15;
            if (pad) {
                uint8_t z[16] = {0};
                poly_update(&aad_st, z, pad);
            }
        }
        /* ciphertext full blocks */
        uint64_t ct_full_blocks = 0;
        uint32_t HC[5] = {0,0,0,0,0};
        int any = 0;
        const uint8_t *tail_ptr = NULL;
        size_t tail_len = 0;
        for (int i = 0; i < NT; i++) {
            worker_t *w = &g_workers[i];
            size_t full = w->len & ~(size_t)15;
            uint64_t blocks = full / 16;
            if (blocks) {
                if (any) {
                    uint32_t rp[5];
                    poly_pow(rp, w->poly.r, blocks);
                    poly_mul(HC, rp);
                }
                poly_add(HC, w->poly.h);
                any = 1;
                ct_full_blocks += blocks;
            }
            if (w->poly.buf_used) {
                tail_ptr = w->poly.buf;
                tail_len = w->poly.buf_used;
            }
        }
        /* Scale AAD accumulator by r^{ct_blocks_padded} and add ciphertext accumulator.
           ct_blocks_padded = full blocks + 1 if tail else full blocks.
           But tail is not a full hibit block — it's a partial block with a 0x01 marker, which is NOT
           equal to multiplying by r. So we cannot fold the tail into the exponent.
           Sequence must be: AAD_state, then full ct blocks, then tail block (partial), then lengths.
           AAD_state * r^{full_blocks} + HC, then poly_update tail, then lengths. */
        if (ct_full_blocks) {
            uint32_t rp[5];
            poly_pow(rp, aad_st.r, ct_full_blocks);
            poly_mul(aad_st.h, rp);
            poly_add(aad_st.h, HC);
        }
        if (tail_len) {
            /* The tail in the worker was fed as a partial block (hibit 0, with 0x01 marker) ONLY if we
               called poly_finish. We did NOT — poly_update stores the tail in buf without absorbing it.
               So tail_ptr is raw leftover ciphertext bytes. Feed them normally. */
            poly_update(&aad_st, tail_ptr, tail_len);
            size_t pad = (16 - (tail_len & 15)) & 15;
            if (pad) {
                uint8_t z[16] = {0};
                poly_update(&aad_st, z, pad);
            }
        } else {
            /* no tail: ct length multiple of 16, no ciphertext padding */
        }
        uint8_t lens[16];
        memset(lens, 0, 16);
        uint64_t al = aad_len, cl = pt_len;
        memcpy(lens, &al, 8);
        memcpy(lens + 8, &cl, 8);
        poly_update(&aad_st, lens, 16);
        poly_finish(&aad_st, tag);
    }
    return 0;
}

/* ---------- Python module ---------- */

static PyObject *py_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)) return NULL;
    if (key.len != 32 || nonce.len != 12) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (aad.buf) PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key/nonce length");
        return NULL;
    }
    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt.len);
    if (!ct_obj) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (aad.buf) PyBuffer_Release(&aad);
        return NULL;
    }
    uint8_t tag[16];
    int rc = aead_encrypt((uint8_t *)PyBytes_AS_STRING(ct_obj), tag,
                          (const uint8_t *)pt.buf, (size_t)pt.len,
                          aad.buf ? (const uint8_t *)aad.buf : NULL, aad.buf ? (size_t)aad.len : 0,
                          (const uint8_t *)key.buf, (const uint8_t *)nonce.buf);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (aad.buf) PyBuffer_Release(&aad);
    if (rc != 0) {
        Py_DECREF(ct_obj);
        PyErr_SetString(PyExc_RuntimeError, "encrypt failed");
        return NULL;
    }
    PyObject *tag_obj = PyBytes_FromStringAndSize((const char *)tag, 16);
    if (!tag_obj) { Py_DECREF(ct_obj); return NULL; }
    PyObject *res = PyTuple_New(2);
    PyTuple_SET_ITEM(res, 0, ct_obj);
    PyTuple_SET_ITEM(res, 1, tag_obj);
    return res;
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moddef = {PyModuleDef_HEAD_INIT, "aead", NULL, -1, methods};
PyMODINIT_FUNC PyInit_aead(void) { return PyModule_Create(&moddef); }
