#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

static inline uint32_t load32(const uint8_t *p){ uint32_t v; memcpy(&v,p,4); return v; }
static inline void store32(uint8_t *p, uint32_t v){ memcpy(p,&v,4); }

typedef struct {
    uint32_t r[5];
    uint32_t h[5];
    uint32_t pad[4];
    uint8_t buf[16];
    size_t buf_used;
    uint32_t s1,s2,s3,s4;
} poly_st;

static void poly_init(poly_st *st, const uint8_t key[32]) {
    memset(st, 0, sizeof(*st));
    uint32_t t0 = load32(key), t1 = load32(key+4), t2 = load32(key+8), t3 = load32(key+12);
    st->r[0] = t0 & 0x3ffffff;
    st->r[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffff03;
    st->r[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffc0ff;
    st->r[3] = ((t2 >> 14) | (t3 << 18)) & 0x3f03fff;
    st->r[4] = (t3 >> 8) & 0x00fffff;
    st->s1 = st->r[1]*5; st->s2=st->r[2]*5; st->s3=st->r[3]*5; st->s4=st->r[4]*5;
    st->pad[0]=load32(key+16); st->pad[1]=load32(key+20); st->pad[2]=load32(key+24); st->pad[3]=load32(key+28);
}
static void poly_blocks(poly_st *st, const uint8_t *m, size_t bytes, uint32_t hibit) {
    const uint32_t r0=st->r[0],r1=st->r[1],r2=st->r[2],r3=st->r[3],r4=st->r[4];
    const uint32_t s1=st->s1,s2=st->s2,s3=st->s3,s4=st->s4;
    uint32_t h0=st->h[0],h1=st->h[1],h2=st->h[2],h3=st->h[3],h4=st->h[4];
    while (bytes >= 16) {
        uint32_t t0=load32(m), t1=load32(m+4), t2=load32(m+8), t3=load32(m+12);
        h0 += t0 & 0x3ffffff;
        h1 += ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
        h2 += ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
        h3 += ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
        h4 += (t3 >> 8) | hibit;
        uint64_t d0=(uint64_t)h0*r0+(uint64_t)h1*s4+(uint64_t)h2*s3+(uint64_t)h3*s2+(uint64_t)h4*s1;
        uint64_t d1=(uint64_t)h0*r1+(uint64_t)h1*r0+(uint64_t)h2*s4+(uint64_t)h3*s3+(uint64_t)h4*s2;
        uint64_t d2=(uint64_t)h0*r2+(uint64_t)h1*r1+(uint64_t)h2*r0+(uint64_t)h3*s4+(uint64_t)h4*s3;
        uint64_t d3=(uint64_t)h0*r3+(uint64_t)h1*r2+(uint64_t)h2*r1+(uint64_t)h3*r0+(uint64_t)h4*s4;
        uint64_t d4=(uint64_t)h0*r4+(uint64_t)h1*r3+(uint64_t)h2*r2+(uint64_t)h3*r1+(uint64_t)h4*r0;
        uint64_t c;
        c=d0>>26; h0=(uint32_t)d0&0x3ffffff; d1+=c;
        c=d1>>26; h1=(uint32_t)d1&0x3ffffff; d2+=c;
        c=d2>>26; h2=(uint32_t)d2&0x3ffffff; d3+=c;
        c=d3>>26; h3=(uint32_t)d3&0x3ffffff; d4+=c;
        c=d4>>26; h4=(uint32_t)d4&0x3ffffff; h0+=(uint32_t)c*5;
        c=h0>>26; h0&=0x3ffffff; h1+=(uint32_t)c;
        m+=16; bytes-=16;
    }
    st->h[0]=h0; st->h[1]=h1; st->h[2]=h2; st->h[3]=h3; st->h[4]=h4;
}
static void poly_update(poly_st *st, const uint8_t *m, size_t bytes){
    if(st->buf_used){
        size_t want=16-st->buf_used; if(want>bytes) want=bytes;
        memcpy(st->buf+st->buf_used,m,want); st->buf_used+=want; m+=want; bytes-=want;
        if(st->buf_used==16){ poly_blocks(st, st->buf, 16, 1u<<24); st->buf_used=0; }
    }
    if(bytes>=16){ size_t n=bytes&~(size_t)15; poly_blocks(st,m,n,1u<<24); m+=n; bytes-=n; }
    if(bytes){ memcpy(st->buf+st->buf_used,m,bytes); st->buf_used+=bytes; }
}
static void poly_finish(poly_st *st, uint8_t mac[16]){
    if(st->buf_used){
        st->buf[st->buf_used]=1;
        for(size_t i=st->buf_used+1;i<16;i++) st->buf[i]=0;
        poly_blocks(st, st->buf, 16, 0);
    }
    uint32_t h0=st->h[0],h1=st->h[1],h2=st->h[2],h3=st->h[3],h4=st->h[4];
    uint32_t c=h1>>26; h1&=0x3ffffff; h2+=c;
    c=h2>>26; h2&=0x3ffffff; h3+=c;
    c=h3>>26; h3&=0x3ffffff; h4+=c;
    c=h4>>26; h4&=0x3ffffff; h0+=c*5;
    c=h0>>26; h0&=0x3ffffff; h1+=c;
    uint32_t g0=h0+5; c=g0>>26; g0&=0x3ffffff;
    uint32_t g1=h1+c; c=g1>>26; g1&=0x3ffffff;
    uint32_t g2=h2+c; c=g2>>26; g2&=0x3ffffff;
    uint32_t g3=h3+c; c=g3>>26; g3&=0x3ffffff;
    uint32_t g4=h4+c-(1u<<26);
    uint32_t mask=(g4>>31)-1u;
    g0&=mask; g1&=mask; g2&=mask; g3&=mask; g4&=mask; mask=~mask;
    h0=(h0&mask)|g0; h1=(h1&mask)|g1; h2=(h2&mask)|g2; h3=(h3&mask)|g3; h4=(h4&mask)|g4;
    uint64_t f0=(h0|((uint64_t)h1<<26))+st->pad[0];
    uint64_t f1=((h1>>6)|((uint64_t)h2<<20))+st->pad[1];
    uint64_t f2=((h2>>12)|((uint64_t)h3<<14))+st->pad[2];
    uint64_t f3=((h3>>18)|((uint64_t)h4<<8))+st->pad[3];
    f1+=f0>>32; f2+=f1>>32; f3+=f2>>32;
    store32(mac,(uint32_t)f0); store32(mac+4,(uint32_t)f1); store32(mac+8,(uint32_t)f2); store32(mac+12,(uint32_t)f3);
}

