/* 8-way AVX2 ChaCha20, speed only */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>
#include <pthread.h>

static inline uint32_t load32(const uint8_t *p){ uint32_t v; memcpy(&v,p,4); return v; }

#define ROTL(x,n) _mm256_or_si256(_mm256_slli_epi32(x,n), _mm256_srli_epi32(x,32-(n)))
#define QR(a,b,c,d) do{ \
  a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=ROTL(d,16); \
  c=_mm256_add_epi32(c,d); b=_mm256_xor_si256(b,c); b=ROTL(b,12); \
  a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=ROTL(d,8); \
  c=_mm256_add_epi32(c,d); b=_mm256_xor_si256(b,c); b=ROTL(b,7); \
} while(0)

/* two independent 4-block groups in one function to increase ILP (8 blocks, 512 bytes) */
static void chacha8(uint8_t *out, const uint8_t *in, const uint32_t key[8], const uint32_t nonce[3], uint32_t counter){
