    __m256i s1=_mm256_set1_epi32(0x3320646e);
    __m256i s2=_mm256_set1_epi32(0x79622d32);
    __m256i s3=_mm256_set1_epi32(0x6b206574);
    __m256i k0=_mm256_set1_epi32(key[0]);
    __m256i k1=_mm256_set1_epi32(key[1]);
    __m256i k2=_mm256_set1_epi32(key[2]);
    __m256i k3=_mm256_set1_epi32(key[3]);
    __m256i k4=_mm256_set1_epi32(key[4]);
    __m256i k5=_mm256_set1_epi32(key[5]);
    __m256i k6=_mm256_set1_epi32(key[6]);
    __m256i k7=_mm256_set1_epi32(key[7]);
    __m256i n0=_mm256_set1_epi32(nonce[0]);
    __m256i n1=_mm256_set1_epi32(nonce[1]);
    __m256i n2=_mm256_set1_epi32(nonce[2]);
    __m256i cA=_mm256_set_epi32(0,0,0,0, counter+3, counter+2, counter+1, counter);
    __m256i cB=_mm256_set_epi32(0,0,0,0, counter+7, counter+6, counter+5, counter+4);

    __m256i a0=s0,a1=s1,a2=s2,a3=s3,a4=k0,a5=k1,a6=k2,a7=k3,a8=k4,a9=k5,a10=k6,a11=k7,a12=cA,a13=n0,a14=n1,a15=n2;
    __m256i b0=s0,b1=s1,b2=s2,b3=s3,b4=k0,b5=k1,b6=k2,b7=k3,b8=k4,b9=k5,b10=k6,b11=k7,b12=cB,b13=n0,b14=n1,b15=n2;

    for(int r=0;r<10;r++){
        QR(a0,a4,a8,a12); QR(a1,a5,a9,a13); QR(a2,a6,a10,a14); QR(a3,a7,a11,a15);
        QR(a0,a5,a10,a15); QR(a1,a6,a11,a12); QR(a2,a7,a8,a13); QR(a3,a4,a9,a14);
        QR(b0,b4,b8,b12); QR(b1,b5,b9,b13); QR(b2,b6,b10,b14); QR(b3,b7,b11,b15);
        QR(b0,b5,b10,b15); QR(b1,b6,b11,b12); QR(b2,b7,b8,b13); QR(b3,b4,b9,b14);
    }
    a0=_mm256_add_epi32(a0,s0); a1=_mm256_add_epi32(a1,s1); a2=_mm256_add_epi32(a2,s2); a3=_mm256_add_epi32(a3,s3);
    a4=_mm256_add_epi32(a4,k0); a5=_mm256_add_epi32(a5,k1); a6=_mm256_add_epi32(a6,k2); a7=_mm256_add_epi32(a7,k3);
    a8=_mm256_add_epi32(a8,k4); a9=_mm256_add_epi32(a9,k5); a10=_mm256_add_epi32(a10,k6); a11=_mm256_add_epi32(a11,k7);
    a12=_mm256_add_epi32(a12,cA); a13=_mm256_add_epi32(a13,n0); a14=_mm256_add_epi32(a14,n1); a15=_mm256_add_epi32(a15,n2);
    b0=_mm256_add_epi32(b0,s0); b1=_mm256_add_epi32(b1,s1); b2=_mm256_add_epi32(b2,s2); b3=_mm256_add_epi32(b3,s3);
    b4=_mm256_add_epi32(b4,k0); b5=_mm256_add_epi32(b5,k1); b6=_mm256_add_epi32(b6,k2); b7=_mm256_add_epi32(b7,k3);
    b8=_mm256_add_epi32(b8,k4); b9=_mm256_add_epi32(b9,k5); b10=_mm256_add_epi32(b10,k6); b11=_mm256_add_epi32(b11,k7);
    b12=_mm256_add_epi32(b12,cB); b13=_mm256_add_epi32(b13,n0); b14=_mm256_add_epi32(b14,n1); b15=_mm256_add_epi32(b15,n2);

    __m256i A[16]={a0,a1,a2,a3,a4,a5,a6,a7,a8,a9,a10,a11,a12,a13,a14,a15};
    __m256i B[16]={b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,b15};
    __attribute__((aligned(32))) uint32_t tmpA[16*4];
    __attribute__((aligned(32))) uint32_t tmpB[16*4];
    for(int i=0;i<16;i++){
        _mm256_store_si256((__m256i*)(tmpA+i*4), A[i]);
        _mm256_store_si256((__m256i*)(tmpB+i*4), B[i]);
    }
    for(int blk=0; blk<4; blk++){
        uint8_t *o=out+blk*64; const uint8_t *inp=in+blk*64;
        for(int i=0;i<16;i++){
            uint32_t v=tmpA[i*4+blk]^load32(inp+4*i);
            memcpy(o+4*i, &v, 4);
        }
    }
    for(int blk=0; blk<4; blk++){
        uint8_t *o=out+256+blk*64; const uint8_t *inp=in+256+blk*64;
        for(int i=0;i<16;i++){
            uint32_t v=tmpB[i*4+blk]^load32(inp+4*i);
            memcpy(o+4*i, &v, 4);
        }
    }
}

static void xor_all(uint8_t *out, const uint8_t *in, size_t n, const uint32_t key[8], const uint32_t nonce[3], uint32_t counter){
    size_t off=0;
    while(off+512<=n){
        chacha8(out+off, in+off, key, nonce, counter);
        off+=512; counter+=8;
    }
    /* ignore tail for speed test */
}

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

typedef struct { uint8_t *out,*in; size_t n; uint32_t key[8]; uint32_t nonce[3]; uint32_t counter; } job;
static void *worker(void *arg){ job *j=arg; xor_all(j->out,j->in,j->n,j->key,j->nonce,j->counter); return NULL; }

int main(){
    size_t n=40000000;
    uint8_t *in=aligned_alloc(64,n), *out=aligned_alloc(64,n);
    memset(in,1,n);
    uint32_t key[8]={0}, nonce[3]={1,2,3};
    /* serial */
    double t0=now();
    int reps=3;
    for(int r=0;r<reps;r++) xor_all(out,in,n,key,nonce,1);
    double t1=now();
    printf("serial 8-way: avg %.2f ms, %.0f MB/s\n", (t1-t0)/reps*1000, 40.0*reps/(t1-t0));

    for(int nt=2; nt<=4; nt*=2){
        size_t chunk=(n/nt)&~511;
        t0=now();
        for(int r=0;r<reps;r++){
            pthread_t th[8]; job jobs[8];
            for(int i=0;i<nt;i++){
                size_t off=i*chunk, len=(i==nt-1)?(n-off)&~511:chunk;
                jobs[i].out=out+off; jobs[i].in=in+off; jobs[i].n=len;
                memcpy(jobs[i].key,key,32); memcpy(jobs[i].nonce,nonce,12);
                jobs[i].counter=1+(uint32_t)(off/64);
                pthread_create(&th[i],NULL,worker,&jobs[i]);
            }
            for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
        }
        t1=now();
        printf("%d thr 8-way: avg %.2f ms, %.0f MB/s\n", nt, (t1-t0)/reps*1000, 40.0*reps/(t1-t0));
    }
    /* correctness of first 64 vs known? print */
    uint8_t small[64]={0};
    uint8_t sout[64];
    uint32_t k2[8]={1,0,0,0,0,0,0,0};
    xor_all(sout, small, 64, k2, nonce, 0);
    printf("out0 %02x %02x\n", sout[0], sout[1]);
    return 0;
}
