        clEnqueueWriteBuffer(q, bin, CL_FALSE, 0, n, in, 0, NULL, NULL);
        clEnqueueNDRangeKernel(q,k,1,NULL,&gs,NULL,0,NULL,NULL);
        clEnqueueReadBuffer(q, bout, CL_FALSE, 0, n, out, 0, NULL, NULL);
