    clFinish(q);
    double t1=now();
    printf("write+chacha+read USE_HOST_PTR: avg %.2f ms\n", (t1-t0)/reps*1000);

    /* map/unmap style */
    t0=now();
    for(int i=0;i<reps;i++){
