    }
    clFinish(q);
    t1=now();
    printf("kernel+map read: avg %.2f ms\n", (t1-t0)/reps*1000);

    /* kernel only, data already resident */
    t0=now();
    for(int i=0;i<reps;i++) clEnqueueNDRangeKernel(q,k,1,NULL,&gs,NULL,0,NULL,NULL);
    clFinish(q);
    t1=now();
    printf("kernel only resident: avg %.2f ms\n", (t1-t0)/reps*1000);
    return 0;
}
