import os
import threading
from typing import Any

from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305

# Fallback path is the reference. The fast path lives in the C extension built below.
try:
    from chacha_fast import encrypt as _fast_encrypt
except Exception:
    _fast_encrypt = None


class Solver:
    def solve(self, problem, **kwargs):
        if _fast_encrypt is not None:
            key = problem["key"]
            nonce = problem["nonce"]
            pt = problem["plaintext"]
            aad = problem.get("associated_data") or b""
            ct, tag = _fast_encrypt(key, nonce, pt, aad)
            return {"ciphertext": ct, "tag": tag}
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        associated_data = problem["associated_data"]
        chacha = ChaCha20Poly1305(key)
