    c=d3>>26; h3=(uint32_t)d3&0x3ffffff; d4+=c;
    c=d4>>26; h4=(uint32_t)d4&0x3ffffff; h0+=(uint32_t)c*5;
    c=h0>>26; h0&=0x3ffffff; h1+=(uint32_t)c;
    h[0]=h0;h[1]=h1;h[2]=h2;h[3]=h3;h[4]=h4;
}
static void poly_pow(uint32_t out[5], const uint32_t r[5], uint64_t n){
    uint32_t base[5]={r[0],r[1],r[2],r[3],r[4]};
    uint32_t acc[5]={1,0,0,0,0};
    while(n){
        if(n&1) poly_mul(acc, base);
        n>>=1;
        if(n){ uint32_t sq[5]={base[0],base[1],base[2],base[3],base[4]}; poly_mul(base, sq); }
    }
    memcpy(out, acc, sizeof(acc));
}
static void poly_add(uint32_t h[5], const uint32_t o[5]){
    uint64_t a0=(uint64_t)h[0]+o[0], a1=(uint64_t)h[1]+o[1], a2=(uint64_t)h[2]+o[2], a3=(uint64_t)h[3]+o[3], a4=(uint64_t)h[4]+o[4];
    uint64_t c;
    c=a0>>26; h[0]=(uint32_t)a0&0x3ffffff; a1+=c;
    c=a1>>26; h[1]=(uint32_t)a1&0x3ffffff; a2+=c;
    c=a2>>26; h[2]=(uint32_t)a2&0x3ffffff; a3+=c;
    c=a3>>26; h[3]=(uint32_t)a3&0x3ffffff; a4+=c;
    c=a4>>26; h[4]=(uint32_t)a4&0x3ffffff; h[0]+=(uint32_t)c*5;
    c=h[0]>>26; h[0]&=0x3ffffff; h[1]+=(uint32_t)c;
}

static void printmac(const char *name, const uint8_t m[16]){
    printf("%s ", name); for(int i=0;i<16;i++) printf("%02x", m[i]); printf("\n");
}

/* Stuff 5 limbs into a fresh openssl context and finalize. */
static void emit_from_h(uint8_t mac[16], const uint8_t key[32], const uint32_t h[5]){
    poly1305_context ctx;
    memset(&ctx, 0, sizeof(ctx));
    Poly1305_Init(&ctx, key);
    uint32_t *hp = (uint32_t*)ctx.opaque;
    hp[0]=h[0]; hp[1]=h[1]; hp[2]=h[2]; hp[3]=h[3]; hp[4]=h[4];
    *(uint32_t*)(ctx.opaque+0x14) = 1; /* is_base2_26 */
    ctx.num = 0;
    Poly1305_Final(&ctx, mac);
}

int main(){
    uint8_t key[32];
    for(int i=0;i<32;i++) key[i]=i*7+3;
    size_t n=4096;
    uint8_t *msg=malloc(n);
    for(size_t i=0;i<n;i++) msg[i]=(uint8_t)(i*3+1);

    poly1305_context serial;
    memset(&serial,0,sizeof(serial));
    Poly1305_Init(&serial, key);
    Poly1305_Update(&serial, msg, n);
    uint8_t mac_ossl[16];
    /* copy before final to also read h */
    poly1305_context saved=serial;
    Poly1305_Final(&serial, mac_ossl);
    printmac("openssl ", mac_ossl);

    uint32_t *oh=(uint32_t*)saved.opaque;
    printf("openssl h: %08x %08x %08x %08x %08x flag %u\n", oh[0],oh[1],oh[2],oh[3],oh[4], *(uint32_t*)(saved.opaque+0x14));

    poly_st mine;
    poly_init(&mine, key);
    poly_blocks(&mine, msg, n);
    printf("mine    h: %08x %08x %08x %08x %08x\n", mine.h[0],mine.h[1],mine.h[2],mine.h[3],mine.h[4]);

    uint8_t mac_stuff[16];
    emit_from_h(mac_stuff, key, mine.h);
    printmac("stuffed mine", mac_stuff);
    uint32_t ossl_h[5]={oh[0],oh[1],oh[2],oh[3],oh[4]};
    emit_from_h(mac_stuff, key, ossl_h);
    printmac("stuffed ossl", mac_stuff);

    /* two-chunk combine with mine's math on openssl h */
    size_t half=n/2;
    poly1305_context c0, c1;
    memset(&c0,0,sizeof(c0)); memset(&c1,0,sizeof(c1));
    Poly1305_Init(&c0, key); Poly1305_Update(&c0, msg, half);
    Poly1305_Init(&c1, key); Poly1305_Update(&c1, msg+half, half);
    uint32_t *h0p=(uint32_t*)c0.opaque, *h1p=(uint32_t*)c1.opaque;
    uint32_t H[5]={h0p[0],h0p[1],h0p[2],h0p[3],h0p[4]};
    uint32_t h1[5]={h1p[0],h1p[1],h1p[2],h1p[3],h1p[4]};
    poly_st rst; poly_init(&rst, key);
    uint32_t rp[5];
    poly_pow(rp, rst.r, half/16);
    poly_mul(H, rp);
    poly_add(H, h1);
    printf("combined: %08x %08x %08x %08x %08x\n", H[0],H[1],H[2],H[3],H[4]);
    printf("ossl full:%08x %08x %08x %08x %08x\n", oh[0],oh[1],oh[2],oh[3],oh[4]);
    emit_from_h(mac_stuff, key, H);
    printmac("combined emit", mac_stuff);
    printf("match serial %d\n", memcmp(mac_stuff, mac_ossl, 16)==0);
    return 0;
}
